-- PREPARED ONLY. Production execution requires explicit approval.
-- Filename generated by the installed Supabase CLI in the external proof directory.
begin;
do $$
begin
    if to_regclass('zh_forum_private.post_reactions') is not null then raise exception 'Reaction table already exists; audit first'; end if;
    if md5(pg_get_functiondef('public.get_zh_forum(text,uuid,integer,integer)'::regprocedure)) <> '3c08fea3ffd26e3e919c2049ffd9936a' then raise exception 'Forum read RPC changed; audit first'; end if;
    if md5(pg_get_functiondef('zh_identity_private.system_role(uuid)'::regprocedure)) <> 'be093779ec15968cc4a565964f2a331c' then raise exception 'Central role function changed; audit first'; end if;
    if not exists(select 1 from pg_constraint where conrelid='zh_forum_private.posts'::regclass and confrelid='zh_forum_private.topics'::regclass and contype='f' and confdeltype='c') then raise exception 'Expected topic/post cascade missing'; end if;
end $$;

create table zh_forum_private.post_reactions (
    post_id uuid not null references zh_forum_private.posts(id) on delete cascade,
    user_id uuid not null references auth.users(id) on delete cascade,
    reaction smallint not null check (reaction in (-1,1)),
    created_at timestamptz not null default clock_timestamp(),
    updated_at timestamptz not null default clock_timestamp(),
    primary key (post_id,user_id)
);
create index post_reactions_user_id_idx on zh_forum_private.post_reactions(user_id);
alter table zh_forum_private.post_reactions enable row level security;
revoke all on zh_forum_private.post_reactions from public,anon,authenticated;

-- Private table has no client policies/grants. Only these bounded checked functions
-- can access it, following the existing forum's private-table / public-wrapper model.
create function zh_forum_private.read_reactions(p_post_ids uuid[]) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare v_user uuid := auth.uid(); v_can boolean; v_posts jsonb;
begin
    if p_post_ids is null or cardinality(p_post_ids)<1 or cardinality(p_post_ids)>50 or array_ndims(p_post_ids)<>1 then
        raise exception 'forum.invalid' using errcode='22023';
    end if;
    if array_position(p_post_ids,null) is not null then
        raise exception 'forum.invalid' using errcode='22023';
    end if;
    v_can := v_user is not null and coalesce(zh_identity_private.system_role(v_user),'') in ('member','admin');
    select coalesce(jsonb_agg(jsonb_build_object('post_id',p.id,'likes',r.likes,'dislikes',r.dislikes,'own_reaction',r.own_reaction) order by p.id),'[]'::jsonb)
    into v_posts
    from zh_forum_private.posts p join zh_forum_private.topics t on t.id=p.topic_id
    cross join lateral (
        select count(*) filter(where x.reaction=1) as likes,count(*) filter(where x.reaction=-1) as dislikes,
            coalesce(max(x.reaction) filter(where x.user_id=v_user and v_can),0) as own_reaction
        from zh_forum_private.post_reactions x where x.post_id=p.id
    ) r
    where p.id=any(p_post_ids) and not p.hidden and not t.hidden;
    return jsonb_build_object('version',1,'can_react',v_can,'posts',v_posts);
end $$;

create function zh_forum_private.set_reaction(p_post_id uuid,p_reaction integer) returns jsonb
language plpgsql security definer set search_path='' as $$
declare v_user uuid := auth.uid(); v_topic uuid;
begin
    if v_user is null or coalesce(zh_identity_private.system_role(v_user),'') not in ('member','admin') then
        raise exception 'identity.signInRequired' using errcode='42501';
    end if;
    if p_post_id is null or p_reaction is null or p_reaction not in (-1,0,1) then raise exception 'forum.invalid' using errcode='22023'; end if;
    -- Same topic-before-post lock order as existing moderation; no activity timestamp changes.
    select t.id into v_topic from zh_forum_private.topics t join zh_forum_private.posts p on p.topic_id=t.id
        where p.id=p_post_id and not p.hidden and not t.hidden for share of t;
    if v_topic is null then raise exception 'forum.notFound' using errcode='P0002'; end if;
    perform 1 from zh_forum_private.posts p where p.id=p_post_id and p.topic_id=v_topic and not p.hidden for share;
    if not found then raise exception 'forum.notFound' using errcode='P0002'; end if;
    -- Serialize the same actor/target even when their neutral state has no row to lock.
    perform pg_advisory_xact_lock(hashtextextended('zh-forum-reaction:'||p_post_id::text||':'||v_user::text,0));
    if p_reaction=0 then
        delete from zh_forum_private.post_reactions where post_id=p_post_id and user_id=v_user;
    else
        insert into zh_forum_private.post_reactions(post_id,user_id,reaction) values(p_post_id,v_user,p_reaction)
        on conflict(post_id,user_id) do update set reaction=excluded.reaction,updated_at=clock_timestamp()
            where post_reactions.reaction<>excluded.reaction;
    end if;
    return zh_forum_private.read_reactions(array[p_post_id]);
end $$;

create function public.get_zh_forum_reactions(p_post_ids uuid[]) returns jsonb
language sql stable security invoker set search_path='' as $$ select zh_forum_private.read_reactions(p_post_ids); $$;
create function public.set_zh_forum_reaction(p_post_id uuid,p_reaction integer) returns jsonb
language sql security invoker set search_path='' as $$ select zh_forum_private.set_reaction(p_post_id,p_reaction); $$;
revoke all on function zh_forum_private.read_reactions(uuid[]),public.get_zh_forum_reactions(uuid[]) from public,anon,authenticated;
revoke all on function zh_forum_private.set_reaction(uuid,integer),public.set_zh_forum_reaction(uuid,integer) from public,anon,authenticated;
grant execute on function zh_forum_private.read_reactions(uuid[]),public.get_zh_forum_reactions(uuid[]) to anon,authenticated;
grant execute on function zh_forum_private.set_reaction(uuid,integer),public.set_zh_forum_reaction(uuid,integer) to authenticated;

-- Only a capability is added to the existing read wrapper. Existing permissions,
-- category/thread data, roles, moderation and view registration stay unchanged.
create or replace function public.get_zh_forum(p_category text default null,p_topic_id uuid default null,p_offset integer default 0,p_post_offset integer default 0)
returns jsonb language sql stable set search_path='' as $$
    select zh_forum_private.read_forum(p_category,p_topic_id,p_offset,p_post_offset)
        ||jsonb_build_object('role_version',1,'moderation_version',2,'views_version',1,'reactions_version',1);
$$;
commit;
